    oninput="document.getElementById('outerRadiusVal').value=(+this.value).toFixed(2);update_outerRadius(+this.value)"></label>
<label>Start angle θ₁: <output id="startAngleVal">π/6</output>
  <input id="startAngleInput" type="range" min="0" max="0.45" step="0.0104166" value="0.1666667"
    oninput="document.getElementById('startAngleVal').value=fmtPi(+this.value);update_startAngle(+this.value)"></label>
<label>End angle θ₂: <output id="endAngleVal">π/4</output>
  <input id="endAngleInput" type="range" min="0.02" max="0.5" step="0.0104166" value="0.25"
    oninput="document.getElementById('endAngleVal').value=fmtPi(+this.value);update_endAngle(+this.value)"></label>
