<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 700, H = 520;
draw.viewbox(0, 0, W, H);

var OX = 50, OY = 468, S = 132;
var COL = { blue: '#28A5D9', fill: '#C4E1F1', red: '#EF5F6B', grey: '#8a8a8a', ink: '#111' };
var SERIF = "Georgia,'Times New Roman',serif";
var PI = Math.PI;

var gGrid = draw.group();
var gRegion = draw.group();
var gRays = draw.group();
var gArcs = draw.group();
var gOverlay = draw.group();
var gAxis = draw.group();
var gLabels = draw.group();

var state = {
  innerRadius: 1.5, outerRadius: 2,
  startAngle: 0.1666667, endAngle: 0.25,
  cartesianOverlay: false
};

/* ---------- geometry helpers ---------- */
function P(r, th) { return [OX + S * r * Math.cos(th), OY - S * r * Math.sin(th)]; }
function fmt(p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }
function arcPath(r, a, b) {
  var R = (S * r).toFixed(2);
  var large = (b - a) > PI ? 1 : 0;
  return 'M' + fmt(P(r, a)) + ' A' + R + ',' + R + ' 0 ' + large + ' 0 ' + fmt(P(r, b));
}
function snapPi(v) { return Math.round(v * 96) / 96; }
function gcd(a, b) { while (b) { var t = a % b; a = b; b = t; } return a; }
function piFrac(v) {
  var n = Math.round(v * 96), d = 96;
  if (n === 0) return { num: '0', den: 1 };
  var g = gcd(Math.abs(n), d) || 1;
  n /= g; d /= g;
  return { num: (n === 1 ? 'π' : n + 'π'), den: d };
}
function fmtPi(v) { var f = piFrac(v); return f.den === 1 ? f.num : f.num + '/' + f.den; }
function trimNum(x) {
  var s = (Math.round(x * 100) / 100).toFixed(2);
  s = s.replace(/0+$/, '').replace(/\.$/, '');
  return s;
}

/* ---------- text helpers ---------- */
function mkText(parent, str, x, y, o) {
  o = o || {};
  var t = parent.plain(str);
  t.attr({
    x: x, y: y,
    'text-anchor': o.anchor || 'start',
    'font-family': o.family || SERIF,
    'font-size': o.size || 16,
    'font-style': o.style || 'normal',
    'font-weight': o.weight || 'normal',
    fill: o.fill || COL.ink
  });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  return t;
}
function tw(t) {
  try { var b = t.bbox(); if (b && b.width) return b.width; } catch (e) { }
  var s = '';
  try { s = t.text(); } catch (e) { }
  return String(s).length * 9;
}
function place(sg, x, y, totalW, anchor, minLeft, maxRight) {
  var dx = (anchor === 'end') ? x - totalW : x;
  if (minLeft != null && dx < minLeft) dx = minLeft;
  if (maxRight != null && dx + totalW > maxRight) dx = maxRight - totalW;
  sg.attr('transform', 'translate(' + dx.toFixed(2) + ',' + y.toFixed(2) + ')');
  return { left: dx, right: dx + totalW, y: y };
}

/* θ = aπ/b  with stacked fraction */
function drawThetaLabel(parent, fr, x, y, size, anchor) {
  var sg = parent.group();
  var pre = mkText(sg, 'θ =', 0, 0, { size: size, style: 'italic', halo: 4 });
  var x0 = tw(pre) + 6, total;
  if (fr.den === 1) {
    var t = mkText(sg, fr.num, x0, 0, { size: size, style: 'italic', halo: 4 });
    total = x0 + tw(t);
  } else {
    var nt = mkText(sg, fr.num, 0, 0, { size: size * 0.95, style: 'italic', halo: 4, anchor: 'middle' });
    var dt = mkText(sg, String(fr.den), 0, 0, { size: size * 0.95, halo: 4, anchor: 'middle' });
    var fw = Math.max(tw(nt), tw(dt)) + 8;
    var cx = x0 + fw / 2;
    nt.attr({ x: cx, y: -size * 0.42 });
    dt.attr({ x: cx, y: size * 0.95 });
    sg.line(x0, -size * 0.16, x0 + fw, -size * 0.16)
      .stroke({ color: COL.ink, width: 1.7, linecap: 'round' })
      .attr({ 'paint-order': 'stroke' });
    total = x0 + fw;
  }
  return place(sg, x, y, total, anchor, 6, W - 6);
}

/* r = value */
function drawRLabel(parent, val, x, y, size, anchor) {
  var sg = parent.group();
  var ri = mkText(sg, 'r', 0, 0, { size: size, style: 'italic', halo: 4 });
  var rest = mkText(sg, ' = ' + val, tw(ri) + 2, 0, { size: size, halo: 4 });
  var total = tw(ri) + 2 + tw(rest);
  return place(sg, x, y, total, anchor, 8, W - 8);
}

/* ---------- static layers ---------- */
(function drawStatic() {
  for (var k = 1; k <= 3; k++) {
    gGrid.path(arcPath(k, -0.02, PI / 2 + 0.02)).fill('none').stroke({ color: '#ececec', width: 1 });
  }
  for (var j = 0; j <= 6; j++) {
    var th = j * PI / 12;
    var p = P(3.35, th);
    gGrid.line(OX, OY, p[0], p[1]).stroke({ color: '#f0f0f0', width: 1 });
  }
  gAxis.line(OX - 12, OY, W - 22, OY).stroke({ color: '#111', width: 2.6, linecap: 'round' });
})();

/* ---------- main redraw ---------- */
function redraw() {
  var ra = +state.innerRadius, rb = +state.outerRadius;
  var r1 = Math.min(ra, rb), r2 = Math.max(ra, rb);
  if (r2 - r1 < 0.05) r2 = r1 + 0.05;
  var a1 = snapPi(Math.min(state.startAngle, state.endAngle));
  var a2 = snapPi(Math.max(state.startAngle, state.endAngle));
  if (a2 - a1 < 1 / 96) a2 = a1 + 1 / 96;
  var t1 = a1 * PI, t2 = a2 * PI;

  gRegion.clear(); gRays.clear(); gArcs.clear(); gOverlay.clear(); gLabels.clear();

  /* --- shaded region --- */
  var R1 = (S * r1).toFixed(2), R2 = (S * r2).toFixed(2);
