}
function place(sg, x, y, totalW, anchor, minLeft, maxRight) {
  var dx = (anchor === 'end') ? x - totalW : x;
  if (minLeft != null && dx < minLeft) dx = minLeft;
  if (maxRight != null && dx + totalW > maxRight) dx = maxRight - totalW;
  sg.attr('transform', 'translate(' + dx.toFixed(2) + ',' + y.toFixed(2) + ')');
  return { left: dx, right: dx + totalW, y: y, width: totalW };
}

/* θ = aπ/b  with a stacked fraction */
function drawThetaLabel(parent, fr, x, y, size, anchor) {
  var sg = parent.group();
  var pre = mkText(sg, 'θ =', 0, 0, { size: size, style: 'italic', halo: 5 });
  var x0 = tw(pre) + 7, total;
  if (fr.den === 1) {
    var t = mkText(sg, fr.num, x0, 0, { size: size, style: 'italic', halo: 5 });
    total = x0 + tw(t);
  } else {
    var nt = mkText(sg, fr.num, 0, 0, { size: size * 0.95, style: 'italic', halo: 5, anchor: 'middle' });
    var dt = mkText(sg, String(fr.den), 0, 0, { size: size * 0.95, halo: 5, anchor: 'middle' });
    var fw = Math.max(tw(nt), tw(dt)) + 9;
    var cx = x0 + fw / 2;
    nt.attr({ x: cx, y: -size * 0.42 });
    dt.attr({ x: cx, y: size * 0.95 });
    sg.line(x0, -size * 0.16, x0 + fw, -size * 0.16)
      .stroke({ color: COL.ink, width: 2, linecap: 'round' })
      .attr({ 'paint-order': 'stroke', stroke: COL.ink });
    total = x0 + fw;
  }
  return place(sg, x, y, total, anchor, 6, W - 6);
}

/* r = value */
function drawRLabel(parent, val, x, y, size, anchor) {
  var sg = parent.group();
  var ri = mkText(sg, 'r', 0, 0, { size: size, style: 'italic', halo: 5 });
  var rest = mkText(sg, ' = ' + val, tw(ri) + 2, 0, { size: size, halo: 5 });
  var total = tw(ri) + 2 + tw(rest);
  return place(sg, x, y, total, anchor, 8, W - 8);
}

/* ---------- main redraw ---------- */
function redraw() {
  var ra = +state.innerRadius, rb = +state.outerRadius;
  var r1 = Math.min(ra, rb), r2 = Math.max(ra, rb);
  if (r2 - r1 < 0.05) r2 = r1 + 0.05;
  var a1 = snapPi(Math.min(state.startAngle, state.endAngle));
  var a2 = snapPi(Math.max(state.startAngle, state.endAngle));
  if (a2 - a1 < 1 / 96) a2 = a1 + 1 / 96;
  var t1 = a1 * PI, t2 = a2 * PI, dth = t2 - t1;

  /* arc overrun past the rays (angular, as in the source figure) */
  var pad = Math.min(0.14, 0.5 * dth);
  var aStart = Math.max(t1 - pad, 0), aEnd = t2 + pad;

  /* ---- auto-fit scale so the wedge fills the frame ---- */
  var cx = Math.cos(aStart), sy = Math.sin(aEnd);
  var sCandX = cx > 0.05 ? (W - 46 - OX) / (r2 * cx) : 1e5;
  var sCandY = sy > 0.05 ? (OY - 76) / (r2 * sy) : 1e5;
  S = Math.max(70, Math.min(560 / r2, sCandX, sCandY));

  gRegion.clear(); gRays.clear(); gArcs.clear(); gOverlay.clear();
  gAxis.clear(); gLabels.clear();

  /* --- polar axis: starts exactly at the pole --- */
  gAxis.line(OX, OY, W - 14, OY).stroke({ color: '#111', width: 2.8, linecap: 'round' });

  /* --- shaded region --- */
  var R1 = (S * r1).toFixed(2), R2 = (S * r2).toFixed(2);
  var d = 'M' + fmt(P(r1, t1)) +
    ' L' + fmt(P(r2, t1)) +
    ' A' + R2 + ',' + R2 + ' 0 0 0 ' + fmt(P(r2, t2)) +
    ' L' + fmt(P(r1, t2)) +
    ' A' + R1 + ',' + R1 + ' 0 0 1 ' + fmt(P(r1, t1)) + ' Z';
  var region = gRegion.path(d).fill(COL.fill).stroke('none').css('cursor', 'pointer');
  region.on('mousemove', function (e) {
    showTooltip('R: ' + trimNum(r1) + ' ≤ r ≤ ' + trimNum(r2) + ',  ' + fmtPi(a1) + ' ≤ θ ≤ ' + fmtPi(a2), e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('The polar rectangle R',
      'R = { (r,θ) : r₁ ≤ r ≤ r₂, θ₁ ≤ θ ≤ θ₂ }. It is a "rectangle" only in the (r,θ) plane: two sides are straight rays of length Δr, but the other two are circular arcs of lengths r₁Δθ and r₂Δθ. Its exact area is ½(r₂²−r₁²)Δθ = r̄ Δr Δθ with r̄ the average radius.');
  });

  /* --- dashed red rays, run out to the edge of the frame --- */
  [t1, t2].forEach(function (th, i) {
    var c = Math.cos(th), s = Math.sin(th);
    var sMaxX = c > 1e-4 ? (W - 10 - OX) / c : 1e5;
    var sMaxY = s > 1e-4 ? (OY - 12) / s : 1e5;
    var L = Math.min(sMaxX, sMaxY);
    var ray = gRays.line(OX, OY, OX + c * L, OY - s * L)
      .stroke({ color: COL.red, width: 2, linecap: 'round', dasharray: '13,9' })
      .css('cursor', 'pointer');
    ray.on('mousemove', function (e) { showTooltip('θ = ' + fmtPi(i ? a2 : a1) + ' (constant angle)', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('A curve θ = constant',
          'Fixing θ and letting r vary traces a straight ray out of the pole. These two rays cut the angular width Δθ = θ₂ − θ₁ of the polar rectangle; sliding them rotates R without changing its radial thickness.');
      });
  });

  /* --- thick blue arcs, over-extended past the rays --- */
  function addArc(r) {
    var a = gArcs.path(arcPath(r, aStart, aEnd))
      .fill('none').stroke({ color: COL.blue, width: 5.4, linecap: 'round' })
      .css('cursor', 'pointer');
    a.on('mousemove', function (e) {
      showTooltip('r = ' + trimNum(r) + ' (constant radius) · arc length = r Δθ = ' + (r * dth).toFixed(3), e);
    }).on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('A curve r = constant',
          'Fixing r and letting θ vary traces a circular arc centred at the pole. Between θ₁ and θ₂ its length is r·Δθ — so the outer arc is longer than the inner one. That growth of arc length with r is exactly the factor r in dA = r dr dθ.');
      });
    return a;
  }
  addArc(r1);
  addArc(r2);

  /* --- optional straight Δr × r₁Δθ rectangle --- */
  if (state.cartesianOverlay) {
    var A = P(r1, t1);
    var uS = [Math.cos(t1), -Math.sin(t1)];
    var vS = [-Math.sin(t1), -Math.cos(t1)];
    var drp = (r2 - r1) * S, arcp = r1 * dth * S;
    var B = [A[0] + uS[0] * drp, A[1] + uS[1] * drp];
    var C = [B[0] + vS[0] * arcp, B[1] + vS[1] * arcp];
    var D = [A[0] + vS[0] * arcp, A[1] + vS[1] * arcp];
    var poly = gOverlay.polygon([A, B, C, D].map(fmt).join(' '))
      .fill({ color: '#8f8f8f', opacity: 0.13 })
      .stroke({ color: '#6b6b6b', width: 1.9, dasharray: '8,6', linejoin: 'round' })
      .css('cursor', 'pointer');
    poly.on('mousemove', function (e) {
      showTooltip('Straight rectangle: Δr × r₁Δθ = ' + ((r2 - r1) * r1 * dth).toFixed(4), e);
    }).on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Why dA = r dr dθ',
          'The flat Δr by r₁Δθ rectangle shares the inner corner of R but its straight sides peel away from the arcs. As Δr and Δθ shrink the mismatch becomes negligible, so the area element is (Δr)(r Δθ) → r dr dθ.');
      });

    var mAB = [(A[0] + B[0]) / 2 - vS[0] * 20, (A[1] + B[1]) / 2 - vS[1] * 20];
    mkText(gOverlay, 'Δr', mAB[0], mAB[1] + 6, { size: 19, style: 'italic', halo: 5, anchor: 'middle', fill: '#444' });
    var mAD = [(A[0] + D[0]) / 2 - uS[0] * 22, (A[1] + D[1]) / 2 - uS[1] * 22];
    mkText(gOverlay, 'r Δθ', mAD[0], mAD[1] + 6, { size: 19, style: 'italic', halo: 5, anchor: 'middle', fill: '#444' });

    mkText(gOverlay, 'area ≈ r Δr Δθ', W - 16, H - 40, { size: 21, style: 'italic', halo: 6, anchor: 'end', fill: '#444' });
  }

  /* --- italic R at the centroid --- */
  var cen = P((r1 + r2) / 2, (t1 + t2) / 2);
  var drpx = (r2 - r1) * S, arcpx = ((r1 + r2) / 2) * dth * S;
  var rSize = Math.max(13, Math.min(34, 0.85 * Math.min(drpx, arcpx)));
  mkText(gLabels, 'R', cen[0], cen[1] + rSize * 0.36,
    { size: rSize, style: 'italic', weight: 'bold', anchor: 'middle', halo: 5 });

  /* --- r labels: up and to the LEFT of each arc end, short leaders --- */
  var Po = P(r2, aEnd), Pi = P(r1, aEnd);
  var yOut = Po[1] - 20, yIn = Pi[1] - 18;
  if (yOut < 30) yOut = 30;
  if (yIn - yOut < 46) yIn = yOut + 46;
  var lo = drawRLabel(gLabels, trimNum(r2), Po[0] - 30, yOut, 26, 'end');
  gLabels.line(lo.right + 7, yOut - 7, Po[0] - 9, Po[1] - 5)
    .stroke({ color: '#4c4c4c', width: 1.4, linecap: 'round' });
  var li = drawRLabel(gLabels, trimNum(r1), Pi[0] - 30, yIn, 26, 'end');
  gLabels.line(li.right + 7, yIn - 7, Pi[0] - 9, Pi[1] - 5)
    .stroke({ color: '#4c4c4c', width: 1.4, linecap: 'round' });

  /* --- θ labels: inside the wedge near the pole, off to each side of its ray --- */
  var rLab = Math.max(0.42 * r1, Math.min(0.85, 0.55 * r1));
  var bLow = P(rLab + 0.1, t1);
  drawThetaLabel(gLabels, piFrac(a1),
    bLow[0] + 34 * Math.sin(t1) + 6, bLow[1] + 34 * Math.cos(t1) + 8, 26, 'start');
  var bUp = P(rLab, t2);
  drawThetaLabel(gLabels, piFrac(a2),
    bUp[0] - 32 * Math.sin(t2) - 6, bUp[1] - 32 * Math.cos(t2) - 4, 26, 'end');

  updateReadout(r1, r2, t1, t2);
}

function updateReadout(r1, r2, t1, t2) {
  var el = document.getElementById('readout');
  if (!el) return;
  var dr = r2 - r1, dth = t2 - t1, rbar = (r1 + r2) / 2;
  var exact = 0.5 * (r2 * r2 - r1 * r1) * dth;
  var rect = dr * r1 * dth;
  var err = exact > 0 ? (exact - rect) / exact * 100 : 0;
  el.innerHTML =
    'Δr = ' + dr.toFixed(3) + '&nbsp;&nbsp;Δθ = ' + dth.toFixed(3) + ' rad<br>' +
    'inner arc r₁Δθ = ' + (r1 * dth).toFixed(3) + '<br>' +
    'outer arc r₂Δθ = ' + (r2 * dth).toFixed(3) + '<br>' +
    'area(R) = ½(r₂²−r₁²)Δθ = ' + exact.toFixed(4) + '<br>' +
    'Δr·(r₁Δθ) = ' + rect.toFixed(4) + '  (' + err.toFixed(1) + '% off)<br>' +
    'Δr·(r̄Δθ) = ' + (dr * rbar * dth).toFixed(4) + '  (exact)';
}

/* ---------- interaction handlers ---------- */
function update_innerRadius(v) { state.innerRadius = v; redraw(); }
function update_outerRadius(v) { state.outerRadius = v; redraw(); }
function update_startAngle(v) { state.startAngle = v; redraw(); }
function update_endAngle(v) { state.endAngle = v; redraw(); }
function toggle_cartesianOverlay(on) { state.cartesianOverlay = !!on; redraw(); }

/* ---------- demo step player ---------- */
var steps = [
  {
    title: 'The region as drawn',
    narration: 'The shaded region R is trapped between the circular arcs r = 1.5 and r = 2 and the rays θ = π/6 and θ = π/4. Its four sides come from just two equations: r = constant and θ = constant.',
    state: { innerRadius: 1.5, outerRadius: 2, startAngle: 0.1666667, endAngle: 0.25, cartesianOverlay: false }
  },
  {
    title: 'Change the radial bounds',
    narration: 'Push the arcs apart while keeping the rays fixed. R grows only in the radial direction — the curved sides slide outward but the straight sides stay on the same two rays.',
    state: { innerRadius: 1, outerRadius: 2.8, startAngle: 0.1666667, endAngle: 0.25, cartesianOverlay: false }
  },
  {
    title: 'Change the angular bounds',
    narration: 'Now fix the radii and open the rays. R sweeps through a wider wedge, and notice the outer edge lengthens more than the inner edge — arc length is r·Δθ, so it depends on how far out you are.',
    state: { innerRadius: 1.5, outerRadius: 2, startAngle: 0.0833333, endAngle: 0.4166667, cartesianOverlay: false }
  },
  {
    title: 'Compare with a true rectangle',
    narration: 'Overlay a straight-sided rectangle of the same Δr by rΔθ dimensions at the inner corner. Its flat sides visibly miss the arcs — R is curved, not a real rectangle.',
    state: { innerRadius: 1.5, outerRadius: 2, startAngle: 0.1666667, endAngle: 0.4166667, cartesianOverlay: true }
  },
  {
    title: 'Shrink toward a differential element',
    narration: 'Make Δr and Δθ small. The straight rectangle and the curved region become indistinguishable, which is exactly why dA = r dr dθ works inside a double integral.',
    state: { innerRadius: 1.7, outerRadius: 1.85, startAngle: 0.1666667, endAngle: 0.2083333, cartesianOverlay: true }
  }
];
var curStep = 0;

function setControls(st) {
  var ir = document.getElementById('innerRadiusInput');
  var or_ = document.getElementById('outerRadiusInput');
  var sa = document.getElementById('startAngleInput');
  var ea = document.getElementById('endAngleInput');
  var ov = document.getElementById('cartesianOverlayInput');
  ir.value = st.innerRadius; or_.value = st.outerRadius;
  sa.value = st.startAngle; ea.value = st.endAngle;
  ov.checked = !!st.cartesianOverlay;
  state.innerRadius = +ir.value;
  state.outerRadius = +or_.value;
  state.startAngle = +sa.value;
  state.endAngle = +ea.value;
  state.cartesianOverlay = !!st.cartesianOverlay;
  document.getElementById('innerRadiusVal').value = state.innerRadius.toFixed(2);
  document.getElementById('outerRadiusVal').value = state.outerRadius.toFixed(2);
  document.getElementById('startAngleVal').value = fmtPi(state.startAngle);
  document.getElementById('endAngleVal').value = fmtPi(state.endAngle);
  redraw();
}

function applyStep(i) {
  curStep = ((i % steps.length) + steps.length) % steps.length;
  var s = steps[curStep];
  setControls(s.state);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

document.addEventListener('fig-resize', function () { redraw(); });

applyStep(0);
window.__markRendered();
